import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Des coins arrondis adoucissent une photo. Ils transforment un rectangle aux angles vifs en une forme accueillante, bien adaptée aux écrans modernes, aux cartes et aux avatars.</p>\n<p>Aujourd’hui, toutes les applications et tous les sites utilisent des coins arrondis. Les photos de profil sont rondes, les cartes ont des bords doux et les boutons sont en forme de pilule : une photo aux coins arrondis y trouve donc naturellement sa place.</p>\n<p>Ce guide explique comment fonctionne l’arrondi, quelles formes choisir et comment exporter le résultat correctement. Il traite du rayon, du réglage coin par coin, de la transparence et des formats. Pour arrondir vos propres images, l’outil <a href=\"/fr/arrondir-coins-image/\">Arrondir les coins d’une image</a> règle le rayon au pixel près, coin par coin, et exporte en PNG avec transparence ou en JPG sur fond uni.</p>\n<h2 id=\"what-rounding-does\">Ce que fait vraiment l’arrondi des coins</h2>\n<p>Arrondir, c’est découper les coins d’une image le long d’une courbe. Les bords droits restent en place, mais les angles à 90 degrés deviennent des arcs lisses.</p>\n<p>La courbe est définie par un rayon. Un petit rayon adoucit à peine les coins, tandis qu’un grand rayon les transforme en courbes profondes qui changent toute la forme.</p>\n<p>L’arrondi ne modifie pas les pixels à l’intérieur de l’image. Il retire seulement les coins, donc la photo elle-même reste exactement aussi nette que l’original.</p>\n<p>Ce qui change, c’est la forme du fichier. Une image arrondie n’est plus un rectangle, et les coins doivent être transparents ou remplis d’une couleur pleine.</p>\n<h2 id=\"radius-explained\">Le rayon des coins, expliqué simplement</h2>\n<p>Le rayon se mesure en pixels, et l’outil affiche sa valeur en direct pendant que vous le réglez. Plus le rayon est grand, plus le coin est rond.</p>\n<p>Un petit rayon de 10 à 20 pixels adoucit les coins juste assez pour qu’on le remarque. Il convient aux cartes, aux miniatures et aux captures d’écran, où l’arrondi doit rester discret.</p>\n<p>Un rayon moyen de 50 à 100 pixels donne un arrondi bien visible. Il convient aux avatars, aux publications sur les réseaux sociaux et aux visuels d’application, où la forme fait partie du design.</p>\n<p>Un très grand rayon transforme l’image en cercle ou en pilule. C’est un changement de forme assumé, pas un adoucissement discret, et il convient aux photos de profil et aux badges.</p>\n<h2 id=\"per-corner-control\">Réglage coin par coin : arrondir un coin à la fois</h2>\n<p>La plupart des images demandent quatre coins arrondis de la même façon, mais certains designs n’en ont besoin que d’un ou deux. Une carte de blog, par exemple, peut avoir des coins supérieurs arrondis et des coins inférieurs carrés.</p>\n<p>Le mode coin par coin permet de définir un rayon différent pour chaque coin. Vous pouvez arrondir les deux du haut et laisser ceux du bas carrés, ou n’arrondir qu’un seul coin pour un effet particulier.</p>\n<p>Si vous désactivez ce mode, un seul rayon s’applique de nouveau aux quatre coins. Les valeurs individuelles sont conservées pendant ce temps, donc vous pouvez revenir en arrière sans perdre vos réglages.</p>\n<p>Utilisez ce réglage avec parcimonie. Un design avec quatre rayons différents a l’air accidentel, alors qu’un ou deux coins arrondis, les autres restant carrés, ont l’air réfléchis.</p>\n<h2 id=\"full-circle-pill\">Cercle complet et forme pilule</h2>\n<p>Le raccourci Cercle complet transforme une image carrée en cercle parfait. Il règle le rayon à la moitié de la taille de l’image, si bien que les coins se courbent tout autour.</p>\n<p>Sur une image rectangulaire, le même raccourci crée une forme pilule : un rectangle aux extrémités entièrement arrondies. Les pilules conviennent aux boutons, aux badges et aux bannières.</p>\n<p>Pour obtenir un cercle bien net, partez d’une photo carrée. Recadrez d’abord l’image en 1:1, puis appliquez le raccourci, et vous obtiendrez un avatar parfaitement rond.</p>\n<p>Vérifiez le résultat sur une photo rectangulaire avant de valider. Une pilule peut être élégante, mais elle peut aussi couper du contenu important sur les côtés.</p>\n<h2 id=\"transparent-vs-solid-fill\">Coins transparents ou remplissage plein</h2>\n<p>Quand les coins sont découpés, l’espace vide doit être rempli par quelque chose. L’outil propose deux choix : transparent, qui laisse les coins translucides, ou une couleur pleine.</p>\n<p>Les coins transparents sont le bon choix pour les visuels web, les avatars et les superpositions. L’image se fond dans n’importe quel arrière-plan, car les coins laissent voir ce qui se trouve derrière.</p>\n<p>Le remplissage plein est le bon choix quand la destination ne gère pas la transparence. Une couleur pleine, comme le blanc, remplit les coins pour que l’image ressemble encore à un rectangle aux bords arrondis.</p>\n<p>Si vous choisissez la transparence alors que le JPG est sélectionné, le format change automatiquement. Le JPG ne gère pas la transparence, donc l’outil vous fait passer en PNG ou en WebP pour garder les coins translucides.</p>\n<h2 id=\"formats-png-webp-jpg\">Formats : PNG, WebP et JPG</h2>\n<p>Le PNG et le WebP gèrent la transparence, donc ils gardent les coins arrondis translucides. Ce sont les bons formats pour les avatars, les logos et tout visuel posé sur un fond coloré.</p>\n<p>Le JPG ne gère pas la transparence : les coins arrondis exportés en JPG reçoivent donc un remplissage plein. Les coins deviennent une couleur pleine, en général blanche, ce qui va bien sur une page blanche mais pas sur un fond coloré.</p>\n<p>Pour les visuels web, le WebP est souvent le meilleur choix. Il donne des fichiers plus petits que le PNG avec la même transparence, même si quelques systèmes anciens refusent encore ce format.</p>\n<p>Pour le résultat le plus net, choisissez le PNG. Il est sans perte, donc les bords courbes restent lisses, et il fonctionne partout, y compris dans les anciens navigateurs et les applications de messagerie.</p>\n<h2 id=\"rounding-for-avatars\">Arrondir les coins pour les avatars et les photos de profil</h2>\n<p>Les avatars sont presque toujours ronds ou arrondis. Une photo carrée aux coins arrondis a l’air moderne, alors qu’un carré aux angles vifs ressemble à un fichier brut.</p>\n<p>Recadrez d’abord la photo en carré, puis arrondissez les coins. Un recadrage 1:1 avec un grand rayon donne un cercle bien net, la forme standard pour un avatar.</p>\n<p>Gardez le visage bien à l’intérieur du cadre. Les coins sont découpés, donc un visage proche du bord peut perdre une oreille ou une partie des cheveux dans la courbe.</p>\n<p>Exportez les avatars en PNG ou en WebP. La transparence garde les coins translucides, donc l’avatar se fond dans n’importe quel fond de profil, clair ou sombre.</p>\n<h2 id=\"rounding-for-cards\">Arrondir les coins pour les cartes et les éléments d’interface</h2>\n<p>Les cartes sont les briques des interfaces modernes, et elles ont presque toujours des coins arrondis. Une photo dont les coins sont arrondis de la même façon s’y insère parfaitement.</p>\n<p>Faites correspondre le rayon de la photo à celui de la carte. Une photo avec un rayon de 16 pixels dans une carte de 16 pixels a l’air harmonieuse, alors que des rayons différents font négligé.</p>\n<p>Pour une carte de blog, arrondissez les deux coins du haut et laissez ceux du bas carrés. La photo se trouve en haut de la carte, et le bas carré s’aligne avec le texte en dessous.</p>\n<p>Gardez le même rayon pour toutes les cartes d’une série. Une grille de cartes aux coins identiques a l’air professionnelle, alors que des rayons mélangés font désordre.</p>\n<h2 id=\"smooth-edges\">Pourquoi les bords courbes paraissent lisses et non crénelés</h2>\n<p>Un bord courbe à l’écran est fait de pixels carrés, donc il devrait paraître crénelé. En pratique, il a l’air lisse, parce que l’outil mélange les pixels du bord avec la couleur de l’arrière-plan.</p>\n<p>Ce mélange s’appelle l’anticrénelage. Les pixels le long de la courbe sont partiellement transparents, ce qui trompe l’œil : il voit une ligne lisse au lieu d’un escalier.</p>\n<p>L’anticrénelage fonctionne le mieux sur un fond transparent. Les pixels mélangés se fondent dans ce qui se trouve derrière l’image, donc la courbe reste nette sur n’importe quelle couleur.</p>\n<p>Sur un remplissage plein, le mélange est moins souple. Les pixels du bord se mélangent à la couleur de remplissage : la courbe paraît lisse sur cette couleur-là, mais rugueuse sur toute autre.</p>\n<h2 id=\"rounding-and-print\">Arrondir les coins pour l’impression</h2>\n<p>Les photos imprimées ont rarement des coins arrondis, car découper un tirage le long d’une courbe demande du travail supplémentaire. Une image arrondie imprimée sur du papier rectangulaire affichera ses coins en remplissage plein.</p>\n<p>Si vous imprimez une image arrondie, choisissez un remplissage plein assorti au papier. Un remplissage blanc sur du papier blanc donne l’impression d’une photo arrondie, alors qu’un export transparent imprimé en JPG reçoit de toute façon un remplissage blanc.</p>\n<p>Pour les autocollants et les étiquettes, les coins arrondis sont justement l’intérêt. Un autocollant aux coins arrondis se décolle proprement et a l’air fini, alors qu’un autocollant aux angles vifs peut accrocher et se soulever.</p>\n<p>Vérifiez la taille d’impression avant d’arrondir. Un petit rayon sur un grand tirage peut être invisible, alors qu’un grand rayon sur un petit tirage peut dominer la forme.</p>\n<h2 id=\"rounding-vs-cropping\">Arrondir ou recadrer : deux tâches différentes</h2>\n<p>Recadrer retire des pixels sur les bords pour changer le cadrage, alors qu’arrondir retire seulement les coins pour changer la forme. Les deux résolvent des problèmes différents.</p>\n<p>Recadrez quand le cadrage ne va pas : trop de ciel, un inconnu au bord, ou un sujet trop petit. L’arrondi ne peut pas corriger un cadrage.</p>\n<p>Arrondissez quand la forme ne va pas : un rectangle aux angles vifs qui semble dur dans une interface moderne. Le recadrage ne peut pas adoucir un coin.</p>\n<p>Utilisez les deux ensemble quand une photo a besoin d’un cadrage et d’une forme. Recadrez d’abord pour corriger la composition, puis arrondissez les coins du résultat pour l’adapter à sa destination.</p>\n<h2 id=\"rounding-and-borders\">Arrondir les coins et ajouter une bordure</h2>\n<p>Les coins arrondis et les bordures vont bien ensemble. Une fine bordure avec un rayon assorti crée un effet carte qui convient aux publications, aux présentations et aux photos de produits.</p>\n<p>Faites correspondre le rayon de la bordure à celui des coins. Une bordure de 16 pixels autour d’une photo de 16 pixels a l’air harmonieuse, alors que des rayons différents font négligé.</p>\n<p>Arrondissez d’abord les coins, puis ajoutez la bordure. L’outil de bordure lit la forme de l’image : arrondir d’abord garde le cadre aligné sur les courbes.</p>\n<p>Pour un style Polaroïd, gardez les coins carrés. Le look classique du film instantané a des coins vifs, et les arrondir casse l’effet rétro.</p>\n<h2 id=\"rounding-on-mobile\">Arrondir les coins sur téléphone ou tablette</h2>\n<p>L’outil fonctionne sur écran tactile : vous pouvez donc arrondir une photo sur le téléphone qui l’a prise. Importez-la depuis votre galerie, faites glisser le curseur du rayon et téléchargez le résultat.</p>\n<p>Utilisez le raccourci Cercle complet pour les avatars sur petit écran. Un seul geste transforme une photo carrée en cercle, ce qui est plus rapide que de faire glisser le curseur jusqu’à la valeur exacte.</p>\n<p>Vérifiez l’aperçu en taille réelle avant de télécharger. Un rayon qui paraît discret sur un petit écran de téléphone peut être plus visible sur un ordinateur.</p>\n<p>Les fichiers téléchargés vont dans votre dossier de téléchargements habituel. De là, vous pouvez définir l’image arrondie comme photo de profil ou la partager directement.</p>\n<h2 id=\"privacy-local-processing\">Confidentialité : arrondir sans rien envoyer</h2>\n<p>Tout l’arrondi des coins se fait dans votre navigateur. Vos photos ne sont jamais envoyées vers un serveur, ce qui compte quand il s’agit de portraits personnels ou de travail pour un client.</p>\n<p>C’est un vrai avantage par rapport aux éditeurs en ligne. Une photo de profil ou un portrait de famille ne devrait pas voyager vers un serveur que vous ne voyez pas, juste pour adoucir ses coins.</p>\n<p>L’outil supprime aussi les données GPS EXIF à l’export. Une photo arrondie téléchargée depuis l’outil ne garde aucune trace du lieu où elle a été prise.</p>\n<p>Gardez la photo originale sans arrondi. Une fois les coins découpés dans un export, on ne peut plus les récupérer depuis ce fichier : l’original est votre seule copie complète.</p>\n<h2 id=\"common-rounding-mistakes\">Les erreurs courantes quand on arrondit les coins</h2>\n<p>L’erreur la plus courante est d’exporter en JPG en espérant garder la transparence. Le JPG ne gère pas la transparence : les coins deviennent un remplissage plein, ce qui fait tache sur un fond coloré.</p>\n<p>Autre erreur : un rayon trop grand pour l’image. Une petite photo avec un rayon énorme devient un cercle, alors qu’on voulait juste un léger arrondi.</p>\n<p>On oublie aussi de recadrer en carré avant de faire un cercle. Une photo rectangulaire avec le raccourci Cercle complet devient une pilule, pas un cercle, et elle risque de ne pas tenir dans l’emplacement prévu pour l’avatar.</p>\n<p>Enfin, n’arrondissez pas plusieurs fois le même JPG. Chaque enregistrement abîme un peu plus le fichier : repartez toujours du fichier original quand vous voulez un autre rayon.</p>\n<h2 id=\"rounding-workflow\">Une méthode pour arrondir proprement</h2>\n<p>Partez du fichier original et décidez d’abord de la destination. Un avatar, une carte et un autocollant demandent des formes différentes : le rayon se choisit donc avant l’arrondi.</p>\n<p>Recadrez dans la bonne forme avant d’arrondir. Un recadrage carré pour un cercle, un recadrage large pour une pilule et un recadrage carte pour une image de blog commencent tous par l’outil de recadrage.</p>\n<p>Vérifiez le résultat arrondi en taille réelle avant de télécharger. Zoomez sur les coins et assurez-vous que les courbes sont lisses et que rien d’important n’a été coupé.</p>\n<p>Enregistrez le fichier arrondi sous un nom clair, par exemple avatar-cercle.png. Vous aurez peut-être besoin de la même forme plus tard, et un nom clair vous évitera de refaire le travail.</p>\n<h2 id=\"rounding-for-stickers\">Arrondir les coins pour les autocollants et les étiquettes</h2>\n<p>Les autocollants et les étiquettes sont plus beaux avec des coins arrondis. Un autocollant aux coins ronds se décolle proprement et a l’air fini, alors qu’un autocollant aux angles vifs peut accrocher et se soulever sur les bords.</p>\n<p>Utilisez un rayon moyen pour les autocollants : assez grand pour se voir, mais assez petit pour ne pas entamer le design. Un rayon trop grand peut couper dans le texte ou dans l’illustration.</p>\n<p>Exportez les autocollants en PNG ou en WebP pour garder les coins transparents. L’autocollant peut alors se poser sur n’importe quel fond, du couvercle d’un ordinateur portable à la couverture d’un carnet, sans cadre blanc.</p>\n<p>Testez l’autocollant à sa taille réelle avant de l’imprimer. Un rayon qui semble correct à l’écran peut être invisible sur un petit autocollant, ou dominer un grand format.</p>\n<p>Pour la marche à suivre pas à pas, consultez <a href=\"/fr/blog/comment-arrondir-coins-image/\">Comment arrondir les coins d’une image</a>. Pour la comparaison, lisez <a href=\"/fr/blog/coins-arrondis-ou-photo-ronde/\">Coins arrondis ou photo ronde : avatar ou carte, que choisir ?</a>, et pour encadrer une photo arrondie, essayez le <a href=\"/fr/ajouter-bordure-a-image/\">générateur de bordures pour images</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Pourquoi mes coins arrondis affichent-ils un fond blanc au lieu d’être transparents ?","answer":"Vous avez sans doute exporté en JPG, qui ne gère pas la transparence. Le JPG remplit les coins découpés d’une couleur pleine, le plus souvent blanche. Exportez plutôt en PNG ou en WebP : ces deux formats gardent les coins translucides sur n’importe quel fond."},{"question":"Comment transformer ma photo en cercle parfait ?","answer":"Recadrez d’abord la photo en carré, puis utilisez le raccourci Cercle complet, qui règle le rayon à la moitié de la taille de l’image. Exportez en PNG ou en WebP pour garder les coins transparents. Une photo rectangulaire deviendra une pilule, pas un cercle."},{"question":"Peut-on arrondir seulement les deux coins du haut d’une image ?","answer":"Oui. Activez le mode coin par coin et réglez un rayon pour les deux coins du haut, en laissant ceux du bas à zéro. C’est idéal pour les cartes de blog, où la photo se trouve en haut et où le bas carré s’aligne avec le texte en dessous."},{"question":"Quel rayon choisir pour une photo de profil ?","answer":"Utilisez le raccourci Cercle complet pour un avatar rond, ou un grand rayon de 50 à 100 pixels pour un carré aux coins bien arrondis. Recadrez d’abord en 1:1 et gardez le visage bien à l’intérieur du cadre, car les coins sont découpés."},{"question":"Arrondir les coins réduit-il la qualité de l’image ?","answer":"Non : l’arrondi retire seulement les coins et laisse le reste des pixels intact. La qualité de la partie conservée reste identique à celle de l’original. Exportez en PNG pour un résultat sans perte, ou en JPG à haute qualité pour les photos."},{"question":"Peut-on arrondir les coins d’une capture d’écran ?","answer":"Oui. Collez la capture avec Ctrl+V, choisissez un petit rayon de 10 à 20 pixels pour un adoucissement discret, et exportez en PNG. La capture arrondie ressemble à une carte d’application moderne et s’intègre bien dans les guides et les présentations."}];
